22	 * @param contextPtr context指针
23	 * @param stream stream
24	 * @param inTensors atb::VariantPack中的输入tensor
25	 * @return atb::Status 错误码
26	 */
27	atb::Status PrepareInTensor(atb::Context *contextPtr, aclrtStream stream, atb::SVector<atb::Tensor> &inTensors)
28	{
29	    // 创建shape为[2, 3]的输入x tensor
30	    atb::Tensor xFloat;
31	    CHECK_STATUS(CreateTensorFromVector(contextPtr, stream, std::vector<float>{1, 2, 3, 4, 5, 6}, ACL_FLOAT16,
32	                                        aclFormat::ACL_FORMAT_ND, {X_DIM_0, X_DIM_1}, xFloat));
33	    // 创建shape为[3, 2]的输入weight tensor
34	    atb::Tensor weightFloat;
35	    CHECK_STATUS(CreateTensorFromVector(contextPtr, stream, std::vector<float>{1, 2, 3, 4, 5, 6}, ACL_FLOAT16,
36	                                        aclFormat::ACL_FORMAT_ND, {WEIGHT_DIM_0, WEIGHT_DIM_1}, weightFloat));
37	    // 创建shape为[1, 2]的输入bias tensor
38	    atb::Tensor biasFloat;
39	    CHECK_STATUS(CreateTensorFromVector(contextPtr, stream, std::vector<float>(BIAS_DIM_0, 1.0), ACL_FLOAT16,
40	                                        aclFormat::ACL_FORMAT_ND, {1, BIAS_DIM_0}, biasFloat));
41	    inTensors = {xFloat, weightFloat, biasFloat};
42	    return atb::ErrorType::NO_ERROR;
43	}
