45	/**
46	 * @brief 创建一个linear operation
47	 * @param linearOp 创建一个Operation指针
48	 * @return atb::Status 错误码
49	 */
50	atb::Status CreateLinearOperation(atb::Operation **linearOp)
51	{
52	    atb::infer::LinearParam param;
53	    param.transposeA = false;
54	    param.transposeB = false;
55	    param.hasBias = true;
56	    param.outDataType = aclDataType::ACL_DT_UNDEFINED;
57	    param.enAccum = false;
